use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    let jobs: Vec<(i64, i64)> = input.as_array().unwrap().iter()
        .map(|v| (v[0].as_i64().unwrap(), v[1].as_i64().unwrap()))
        .collect();

    let mut finish_times = vec![0; jobs.len()];
    let mut current_time = 0;

    for (i, (arrival, duration)) in jobs.iter().enumerate() {
        current_time = current_time.max(*arrival) + *duration;
        finish_times[i] = current_time;
    }

    Value::Array(finish_times.into_iter().map(|t| Value::from(t)).collect())
}
